var next: [8][8]bool = undefined;
for (0..8) |r| {
    for (0..8) |c| {
        var count: u32 = 0;
        var dr: i32 = -1;
        while (dr <= 1) : (dr += 1) {
            var dc: i32 = -1;
            while (dc <= 1) : (dc += 1) {
                if (dr == 0 and dc == 0)
                    continue;
                const rr = @as(i32, @intCast(r)) + dr;
                const cc = @as(i32, @intCast(c)) + dc;
                if (rr >= 0 and rr < 8 and cc >= 0 and cc < 8 and board[@intCast(rr)][@intCast(cc)])
                    count += 1;
        next[r][c] = count == 3 or (board[r][c] and count == 2);
board = next;
